import zipfile

with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as zf:
    for name in zf.namelist():
        if name.endswith('stops.txt'):
            content = zf.read(name).decode('utf-8')
            lines = content.strip().split('\n')
            header = lines[0].split(',')
            stop_ids = set()
            valid_stops = []
            for line in lines[1:]:
                parts = line.strip().split(',')
                if len(parts) == 4:
                    stop_id = parts[0]
                    stop_name = parts[1]
                    stop_lat = parts[2]
                    stop_lon = parts[3]
                    # Check for duplicate stop_ids
                    if stop_id in stop_ids:
                        continue
                    # Check for blank stop_name
                    if not stop_name.strip():
                        continue
                    # Check for escaped characters (like \\u00b7)
                    stop_name = stop_name.replace('\\\\u00b7', '•')  # Convert Unicode bullet
                    # Check for invalid coordinates (outside -180 to 180, 0 to 90)
                    try:
                        lat = float(stop_lat)
                        lon = float(stop_lon)
                        if not (-180 <= lat <= 90 and -180 <= lon <= 180):
                            continue
                    except ValueError:
                        continue
                    stop_ids.add(stop_id)
                    valid_stops.append({
                        'stop_id': stop_id,
                        'stop_name': stop_name.strip(),
                        'stop_lat': stop_lat,
                        'stop_lon': stop_lon
                    })
            # Check for invalid coordinates
            invalid_coords = []
            for stop in valid_stops:
                try:
                    lat = float(stop['stop_lat'])
                    lon = float(stop['stop_lon'])
                    if not (-180 <= lat <= 90 and -180 <= lon <= 180):
                        invalid_coords.append(stop)
                except ValueError:
                    invalid_coords.append(stop)
            # Check for missing stop names
            missing_names = [stop for stop in valid_stops if not stop['stop_name']]
            print(f'Invalid coordinates: {len(invalid_coords)}')
            for s in invalid_coords:
                print(f'  {s[\"stop_id\"]}: lat={s[\"stop_lat\"]}, lon={s[\"stop_lon\"]}')
            print(f'Missing stop names: {len(missing_names)}')
            for s in missing_names:
                print(f'  {s[\"stop_id\"]}: {repr(s[\"stop_name\"])}')
            break
""}

